function hrep($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function nrep($v,$def=0){$s=trim(str_replace(array('$',' '),'',(string)$v));if($s==='')return (float)$def;if(strpos($s,',')!==false)$s=str_replace(',','.',str_replace('.','',$s));return is_numeric($s)?(float)$s:(float)$def;}
function repTablaExiste(mysqli $c,string $t):bool{return esquemaTablaExiste($c,$t);}
function repBejermanExiste(mysqli $c,string $codigo):bool{$st=$c->prepare("SELECT 1 FROM bejerman_productos bp INNER JOIN bejerman_listas bl ON bl.bejerman_lista_id=bp.bejerman_lista_id AND bl.estado='VIGENTE' WHERE UPPER(bp.codigo)=UPPER(?) LIMIT 1");$st->bind_param('s',$codigo);$st->execute();$ok=(bool)$st->get_result()->fetch_row();$st->close();return $ok;}

$mensaje='';$error='';
if(!empty($estadoCatalogoV163['migracion_ejecutada']))$mensaje='Catálogo de Repuestos instalado automáticamente y costos recalculados.';
if(empty($estadoCatalogoV163['ok']))$error='No se pudo completar la instalación automática del catálogo: '.($estadoCatalogoV163['mensaje']??'error desconocido');
$tab=(string)($_GET['tab']??'catalogo');
$tabs=array('catalogo','categorias','integracion','equivalencias','dependencias');
if(!in_array($tab,$tabs,true))$tab='catalogo';

if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  $accion=(string)($_POST['accion']??'guardar_producto');
  if($accion==='recalcular'){
   $r=repCostoRecalcularTodos($conexion,0);$mensaje='Costos recalculados: '.(int)$r['actualizados'].'. Sin costo: '.(int)$r['sin_costo'].'.';$tab='catalogo';
  }elseif($accion==='guardar_categoria'){
   if(!repTablaExiste($conexion,'repuestos_categorias'))throw new Exception('Importe primero migracion_mantenimiento_repuestos_v225.sql.');
   $id=(int)($_POST['categoria_id']??0);$nombre=trim((string)($_POST['categoria_nombre']??''));$orden=(int)($_POST['categoria_orden']??100);$act=isset($_POST['categoria_activa'])?1:0;
   if($nombre==='')throw new Exception('Ingrese el nombre de la categoría.');
   if($id>0){$st=$conexion->prepare("UPDATE repuestos_categorias SET categoria_nombre=?,categoria_orden=?,categoria_activa=? WHERE categoria_id=?");$st->bind_param('siii',$nombre,$orden,$act,$id);$st->execute();$st->close();$mensaje='Categoría actualizada.';}
   else{$st=$conexion->prepare("INSERT INTO repuestos_categorias(categoria_nombre,categoria_orden,categoria_activa) VALUES(?,?,?)");$st->bind_param('sii',$nombre,$orden,$act);$st->execute();$st->close();$mensaje='Categoría creada.';}
   $tab='categorias';
  }elseif($accion==='guardar_regla'){
   if(!repTablaExiste($conexion,'repuestos_reglas_integracion'))throw new Exception('Importe primero migracion_mantenimiento_repuestos_v225.sql.');
   $id=(int)($_POST['regla_id']??0);$mod=strtoupper(trim((string)($_POST['origen_modulo']??'GENERAL')));$tipo=strtoupper(trim((string)($_POST['origen_tipo']??'MODULO')));$valor=trim((string)($_POST['origen_valor']??'*'));$prod=(int)($_POST['producto_repuesto_id']??0);$comp=strtoupper(trim((string)($_POST['comportamiento']??'SUGERIR')));$ct=strtoupper(trim((string)($_POST['cantidad_tipo']??'FIJA')));$cv=nrep($_POST['cantidad_valor']??1,1);$prio=(int)($_POST['prioridad']??100);$act=isset($_POST['activo'])?1:0;$obs=trim((string)($_POST['observaciones']??''));
   if(!in_array($mod,array('GENERAL','CONTROL','SENALIZACION','ACCESORIOS','IEP'),true))throw new Exception('Módulo de origen inválido.');
   if($prod<=0)throw new Exception('Seleccione el repuesto destino.');
   if($valor==='')$valor='*';
   if($id>0){$st=$conexion->prepare("UPDATE repuestos_reglas_integracion SET origen_modulo=?,origen_tipo=?,origen_valor=?,producto_repuesto_id=?,comportamiento=?,cantidad_tipo=?,cantidad_valor=?,prioridad=?,activo=?,observaciones=? WHERE regla_id=?");$st->bind_param('sssissdiisi',$mod,$tipo,$valor,$prod,$comp,$ct,$cv,$prio,$act,$obs,$id);$st->execute();$st->close();$mensaje='Regla de integración actualizada.';}
   else{$st=$conexion->prepare("INSERT INTO repuestos_reglas_integracion(origen_modulo,origen_tipo,origen_valor,producto_repuesto_id,comportamiento,cantidad_tipo,cantidad_valor,prioridad,activo,observaciones) VALUES(?,?,?,?,?,?,?,?,?,?)");$st->bind_param('sssissdiis',$mod,$tipo,$valor,$prod,$comp,$ct,$cv,$prio,$act,$obs);$st->execute();$st->close();$mensaje='Regla de integración creada.';}
   $tab='integracion';
  }elseif($accion==='guardar_equivalencia'){
   $id=(int)($_POST['equivalencia_id']??0);$ori=strtoupper(trim((string)($_POST['codigo_origen']??'')));$des=strtoupper(trim((string)($_POST['codigo_destino']??'')));$desc=trim((string)($_POST['equivalencia_descripcion']??''));$act=isset($_POST['equivalencia_activa'])?'SI':'NO';
   if($ori===''||$des==='')throw new Exception('Ingrese código origen y código destino.');
   if($id>0){$st=$conexion->prepare("UPDATE equivalencias_codigos SET codigo_origen=?,codigo_destino=?,equivalencia_descripcion=?,equivalencia_activa=? WHERE equivalencia_id=?");$st->bind_param('ssssi',$ori,$des,$desc,$act,$id);$st->execute();$st->close();$mensaje='Equivalencia actualizada.';}
   else{$st=$conexion->prepare("INSERT INTO equivalencias_codigos(codigo_origen,codigo_destino,equivalencia_descripcion,equivalencia_activa) VALUES(?,?,?,?)");$st->bind_param('ssss',$ori,$des,$desc,$act);$st->execute();$st->close();$mensaje='Equivalencia creada.';}
   $tab='equivalencias';
  }else{
   $id=(int)($_POST['producto_repuesto_id']??0);$codigo=strtoupper(trim((string)($_POST['codigo']??'')));$descripcion=trim((string)($_POST['descripcion']??''));$categoria=trim((string)($_POST['categoria']??''));$tipo=repCostoTipoNormalizar($_POST['costo_tipo']??'BEJERMAN');$formula=trim((string)($_POST['formula_costo']??''));$fijo=nrep($_POST['costo_fijo']??'',0);$utilidad=nrep($_POST['utilidad']??'',1);$f15=nrep($_POST['factor_descuento_15']??'',.85);$f30=nrep($_POST['factor_descuento_30']??'',.70);$iva=nrep($_POST['iva_porcentaje']??'',21);$obs=trim((string)($_POST['observaciones']??''));$adv=trim((string)($_POST['advertencia']??''));$neto=isset($_POST['es_neto'])?1:0;$habilitado=isset($_POST['habilitado'])?1:0;
   if($codigo==='')throw new Exception('Ingrese el código del repuesto.');if($descripcion==='')throw new Exception('Ingrese la descripción del repuesto.');if($utilidad<=0)throw new Exception('La utilidad debe ser mayor que cero.');if($tipo==='FORMULA'&&$formula==='')throw new Exception('El tipo FORMULA requiere una fórmula de costo.');if($tipo!=='FORMULA')$formula='';if($tipo!=='FIJO')$fijo=0;
   if($id>0){$st=$conexion->prepare("SELECT producto_repuesto_id FROM productos_repuestos WHERE UPPER(codigo)=UPPER(?) AND producto_repuesto_id<>? LIMIT 1");$st->bind_param('si',$codigo,$id);$st->execute();if($st->get_result()->fetch_assoc())throw new Exception('Ya existe otro repuesto con ese código.');$st->close();$st=$conexion->prepare("UPDATE productos_repuestos SET codigo=?,descripcion=?,categoria=?,costo_tipo=?,formula_costo=NULLIF(?,''),costo_fijo=CASE WHEN ?='FIJO' THEN ? ELSE NULL END,utilidad=?,factor_descuento_15=?,factor_descuento_30=?,observaciones=?,es_neto=?,iva_porcentaje=?,advertencia=?,habilitado=? WHERE producto_repuesto_id=?");$st->bind_param('ssssssddddsidsii',$codigo,$descripcion,$categoria,$tipo,$formula,$tipo,$fijo,$utilidad,$f15,$f30,$obs,$neto,$iva,$adv,$habilitado,$id);$st->execute();$st->close();$mensaje='Repuesto actualizado correctamente.';}
   else{$st=$conexion->prepare("SELECT producto_repuesto_id FROM productos_repuestos WHERE UPPER(codigo)=UPPER(?) LIMIT 1");$st->bind_param('s',$codigo);$st->execute();if($st->get_result()->fetch_assoc())throw new Exception('El código ya existe. Búsquelo y edítelo.');$st->close();$st=$conexion->prepare("INSERT INTO productos_repuestos(codigo,descripcion,categoria,costo_referencia,costo_tipo,formula_costo,costo_fijo,utilidad,factor_descuento_15,factor_descuento_30,observaciones,es_neto,iva_porcentaje,advertencia,habilitado) VALUES(?,?,?,0,?,NULLIF(?,''),CASE WHEN ?='FIJO' THEN ? ELSE NULL END,?,?,?,?,?,?,?,?)");$st->bind_param('ssssssddddsidsi',$codigo,$descripcion,$categoria,$tipo,$formula,$tipo,$fijo,$utilidad,$f15,$f30,$obs,$neto,$iva,$adv,$habilitado);$st->execute();$st->close();$mensaje='Nuevo repuesto agregado correctamente.';}
   repCostoRecalcularTodos($conexion,0);$tab='catalogo';
  }
 }catch(Throwable $e){$error=$e->getMessage();}
