$recalculoVistaV164=array('actualizados'=>0,'sin_costo'=>0,'errores'=>array(),'lista_id'=>0);
$q=trim((string)($_GET['q']??''));$cat=trim((string)($_GET['categoria']??''));$tipoFiltro=trim((string)($_GET['tipo']??''));$estado=(string)($_GET['estado']??'habilitados');$where=array('1=1');$params=array();$types='';if($q!==''){foreach(preg_split('/\s+/u',$q,-1,PREG_SPLIT_NO_EMPTY) as $t){$where[]="CONCAT_WS(' ',codigo,descripcion,categoria,COALESCE(observaciones,''),COALESCE(advertencia,''),COALESCE(formula_costo,'')) LIKE ?";$params[]='%'.$t.'%';$types.='s';}}if($cat!==''){$where[]='categoria=?';$params[]=$cat;$types.='s';}if(in_array($tipoFiltro,array('BEJERMAN','FORMULA','FIJO'),true)){$where[]='costo_tipo=?';$params[]=$tipoFiltro;$types.='s';}if($estado==='habilitados')$where[]='habilitado=1';elseif($estado==='deshabilitados')$where[]='habilitado=0';$sql="SELECT *,(costo_referencia*utilidad) precio_base FROM productos_repuestos WHERE ".implode(' AND ',$where)." ORDER BY categoria,descripcion LIMIT 300";$st=$conexion->prepare($sql);if($types!=='')$st->bind_param($types,...$params);$st->execute();$rs=$st->get_result();
$cats=$conexion->query("SELECT DISTINCT categoria FROM productos_repuestos WHERE COALESCE(categoria,'')<>'' ORDER BY categoria");$stats=$conexion->query("SELECT COUNT(*) total,SUM(habilitado=1) habilitados,SUM(costo_tipo='FORMULA') formulas,SUM(costo_tipo='FIJO') fijos,SUM(habilitado=1 AND costo_referencia<=0) sin_costo FROM productos_repuestos")->fetch_assoc();
$categorias=repTablaExiste($conexion,'repuestos_categorias')?$conexion->query("SELECT * FROM repuestos_categorias ORDER BY categoria_orden,categoria_nombre"):false;
$reglas=repTablaExiste($conexion,'repuestos_reglas_integracion')?$conexion->query("SELECT r.*,p.codigo,p.descripcion FROM repuestos_reglas_integracion r INNER JOIN productos_repuestos p ON p.producto_repuesto_id=r.producto_repuesto_id ORDER BY r.activo DESC,r.prioridad,r.origen_modulo,r.regla_id"):false;
$productosRegla=$conexion->query("SELECT producto_repuesto_id,codigo,descripcion FROM productos_repuestos WHERE habilitado=1 ORDER BY codigo LIMIT 2000");
$equiv=$conexion->query("SELECT e.* FROM equivalencias_codigos e WHERE EXISTS(SELECT 1 FROM productos_repuestos p WHERE UPPER(p.codigo) COLLATE utf8mb4_general_ci = UPPER(e.codigo_origen) COLLATE utf8mb4_general_ci OR UPPER(p.codigo) COLLATE utf8mb4_general_ci = UPPER(e.codigo_destino) COLLATE utf8mb4_general_ci) ORDER BY e.equivalencia_activa DESC,e.codigo_origen LIMIT 500");
$deps=$conexion->query("SELECT p.producto_repuesto_id,p.codigo,p.descripcion,p.habilitado,(SELECT COUNT(*) FROM cotizaciones_detalle d WHERE UPPER(d.codigo) COLLATE utf8mb4_unicode_ci = UPPER(p.codigo) COLLATE utf8mb4_unicode_ci) cotizaciones,(SELECT COUNT(*) FROM pedidos_detalle d WHERE UPPER(d.codigo) COLLATE utf8mb4_unicode_ci = UPPER(p.codigo) COLLATE utf8mb4_unicode_ci) pedidos,".(repTablaExiste($conexion,'repuestos_reglas_integracion')?"(SELECT COUNT(*) FROM repuestos_reglas_integracion r WHERE r.producto_repuesto_id=p.producto_repuesto_id)":"0")." reglas FROM productos_repuestos p WHERE p.habilitado=1 ORDER BY (cotizaciones+pedidos+reglas) DESC,p.codigo LIMIT 300");
?>
